"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[70],{9116:function(e,a,o){o.d(a,{G:function(){return d}});var s=o(7437),r=o(521),i=o(401),n=o(2371),t=o(5315);function d(e){let{article:a,onRead:o}=e,d=(0,n.o)(e=>!!e.activities["read:".concat(a.slug)]),m=(0,n.o)(e=>e.addActivity);return(0,s.jsxs)("article",{children:[(0,s.jsxs)("div",{className:"rounded-4xl bg-gradient-to-br from-rose-100 to-lilac-200 p-6 text-center",children:[(0,s.jsx)("p",{className:"text-5xl",children:a.emoji}),(0,s.jsx)("h1",{className:"mt-2 text-2xl font-bold leading-tight",children:a.title}),(0,s.jsxs)("p",{className:"mt-1 text-xs font-bold text-grape-600",children:[a.minutes," min de leitura"]})]}),(0,s.jsx)("p",{className:"mt-5 text-[15px] leading-relaxed text-ink",children:a.intro}),a.sections.map((e,a)=>(0,s.jsxs)(r.E.section,{initial:{opacity:0,y:10},whileInView:{opacity:1,y:0},viewport:{once:!0},transition:{delay:.03*a},className:"mt-5",children:[(0,s.jsx)("h2",{className:"text-lg font-bold text-grape-700",children:e.h}),e.p.map(e=>(0,s.jsx)("p",{className:"mt-2 text-[15px] leading-relaxed text-ink-soft",children:e},e))]},e.h)),(0,s.jsx)("button",{disabled:d&&!o,onClick:()=>{m("read:".concat(a.slug)),null==o||o()},className:"mt-8 w-full ".concat(d?"btn-soft":"btn-primary shine"),children:d?(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(i.Z,{size:18})," Leitura conclu\xedda"]}):"Li at\xe9 o fim \xb7 +".concat(t.Er.read," pts")})]})}},4964:function(e,a,o){o.d(a,{N:function(){return r},w:function(){return s}});let s=[{slug:"fundamentos",title:"Fundamentos do Pilates na Parede",emoji:"\uD83E\uDDF1",minutes:4,intro:'O Pilates foi criado por Joseph Pilates no come\xe7o do s\xe9culo XX como um m\xe9todo de condicionamento que une for\xe7a, controle e consci\xeancia corporal. Na vers\xe3o com parede, ela vira o seu "aparelho": d\xe1 apoio, resist\xeancia e refer\xeancia de alinhamento.',sections:[{h:"Os 6 princ\xedpios",p:["Concentra\xe7\xe3o: cada movimento \xe9 feito com aten\xe7\xe3o total, n\xe3o no autom\xe1tico.","Controle: nenhum movimento \xe9 jogado; voc\xea conduz o corpo do in\xedcio ao fim.","Centro: o abd\xf4men profundo, o assoalho p\xe9lvico e os m\xfasculos das costas formam a base de tudo.","Respira\xe7\xe3o: a expira\xe7\xe3o acompanha o esfor\xe7o e ajuda a estabilizar o tronco.","Precis\xe3o: poucas repeti\xe7\xf5es bem feitas valem mais que muitas apressadas.","Fluidez: com o tempo, os movimentos se encadeiam de forma cont\xednua."]},{h:"Por que a parede ajuda",p:["A parede mostra se a coluna est\xe1 alinhada: quando quadril, costas e cabe\xe7a encostam, voc\xea tem uma refer\xeancia clara de postura.","Ela tamb\xe9m serve de apoio para equil\xedbrio e de superf\xedcie para empurrar, criando resist\xeancia sem nenhum equipamento."]},{h:"O que voc\xea precisa",p:["Uma parede livre de quadros e tomadas na altura do corpo, um tapete ou toalha dobrada e roupas confort\xe1veis. Pode treinar descal\xe7a ou com meias antiderrapantes."]}]},{slug:"respiracao",title:"Como respirar durante os exerc\xedcios",emoji:"\uD83C\uDF2C️",minutes:3,intro:"No Pilates usamos a respira\xe7\xe3o lateral (ou intercostal): o ar expande as costelas para os lados e para tr\xe1s, enquanto o abd\xf4men continua levemente ativo.",sections:[{h:"Passo a passo",p:["Coloque as m\xe3os nas laterais das costelas.","Inspire pelo nariz sentindo as costelas abrirem contra as m\xe3os, sem estufar a barriga.","Expire pela boca, devagar, como se soprasse uma vela sem apag\xe1-la, e sinta as costelas se fecharem."]},{h:"Quando inspirar e expirar",p:["Regra geral: expire no momento de maior esfor\xe7o (subir a ponte, empurrar a parede, elevar a perna) e inspire ao voltar.","Nas sustenta\xe7\xf5es (prancha, agachamento isom\xe9trico), respire continuamente. Prender o ar aumenta a press\xe3o no tronco e cansa mais r\xe1pido."]},{h:"Respira\xe7\xe3o para acalmar",p:["Expirar por mais tempo do que inspira (por exemplo, 4 tempos para inspirar e 6 para expirar) \xe9 uma forma simples de desacelerar depois do treino ou antes de dormir."]}]},{slug:"adaptar",title:"Como adaptar os movimentos",emoji:"\uD83E\uDE84",minutes:3,intro:'Adaptar n\xe3o \xe9 fazer "menos": \xe9 fazer o exerc\xedcio certo para o seu corpo hoje. Todo exerc\xedcio do desafio tem uma vers\xe3o mais f\xe1cil no bot\xe3o "Vers\xe3o mais f\xe1cil".',sections:[{h:"As 4 alavancas de adapta\xe7\xe3o",p:["Amplitude: fa\xe7a um movimento menor. Um agachamento curto ainda fortalece.","Inclina\xe7\xe3o: nos exerc\xedcios em p\xe9 de frente para a parede, aproxime os p\xe9s dela para deixar mais leve.","Tempo: reduza a sustenta\xe7\xe3o ou fa\xe7a menos repeti\xe7\xf5es, mantendo a qualidade.","Apoio: use a parede, as m\xe3os ou dobre os joelhos sempre que precisar."]},{h:"Limita\xe7\xf5es informadas no in\xedcio",p:["Se voc\xea marcou joelhos, lombar, punhos, ombros ou pesco\xe7o no seu perfil, o app j\xe1 troca automaticamente os exerc\xedcios que costumam sobrecarregar essas regi\xf5es. Voc\xea pode mudar isso no Perfil a qualquer momento."]},{h:"Quando ficou f\xe1cil",p:["Se terminar as s\xe9ries sentindo que poderia fazer muito mais, aumente o desafio no Perfil (n\xedvel intermedi\xe1rio ou avan\xe7ado) ou escolha mais minutos por dia."]}]},{slug:"postura",title:"Postura no cotidiano",emoji:"\uD83E\uDDCD‍♀️",minutes:4,intro:'A postura n\xe3o \xe9 uma posi\xe7\xe3o fixa e "perfeita": \xe9 a capacidade de mudar de posi\xe7\xe3o com conforto. Ainda assim, alguns ajustes simples fazem muita diferen\xe7a ao longo do dia.',sections:[{h:"No celular",p:['Traga o celular para a altura dos olhos em vez de descer a cabe\xe7a. Cada vez que voc\xea lembrar, fa\xe7a um "queixo duplo" suave para realinhar o pesco\xe7o.']},{h:"Sentada",p:["Apoie os dois p\xe9s no ch\xe3o, sente sobre os \xedsquios (os ossinhos do bumbum) e use um apoio atr\xe1s da lombar se a cadeira for funda. Levante-se a cada 45–60 minutos, nem que seja para pegar \xe1gua."]},{h:"Carregando peso",p:["Divida as sacolas entre as duas m\xe3os, mantenha o peso perto do corpo e dobre os joelhos para pegar algo do ch\xe3o, ativando o abd\xf4men como no Pilates."]},{h:"O teste da parede",p:["Encoste calcanhares, quadril, costas e cabe\xe7a na parede por 30 segundos. Perceba onde o corpo encosta com facilidade e onde n\xe3o: esse \xe9 um \xf3timo lembrete do alinhamento que voc\xea treina no desafio."]}]},{slug:"recuperacao",title:"Recupera\xe7\xe3o e descanso",emoji:"\uD83C\uDF19",minutes:3,intro:"O treino \xe9 o est\xedmulo; a adapta\xe7\xe3o acontece no descanso. \xc9 por isso que o desafio tem dias de mobilidade e recupera\xe7\xe3o ativa.",sections:[{h:"Dor muscular \xe9 normal?",p:["Uma sensibilidade leve nos m\xfasculos 24 a 48 horas depois de um treino novo \xe9 comum e tende a diminuir com a regularidade. Dor aguda, pontada, incha\xe7o ou dor na articula\xe7\xe3o n\xe3o s\xe3o normais: pause e, se persistir, procure um profissional de sa\xfade."]},{h:"Sono",p:["Dormir bem ajuda na recupera\xe7\xe3o muscular, no humor e no apetite. Tente manter hor\xe1rios parecidos para dormir e acordar, inclusive nos fins de semana."]},{h:"Recupera\xe7\xe3o ativa",p:['Nos dias leves, movimentos suaves (mobilidade, caminhada, alongamento) ajudam a circula\xe7\xe3o e a sensa\xe7\xe3o de corpo "solto" sem gerar cansa\xe7o extra.']}]},{slug:"alongamentos",title:"Alongamentos r\xe1pidos",emoji:"\uD83E\uDD38‍♀️",minutes:3,intro:"Quatro alongamentos com a parede para qualquer pausa do dia. Fique de 20 a 40 segundos em cada um, respirando devagar.",sections:[{h:"1. Peitoral na parede",p:["Antebra\xe7o apoiado na parede na altura do ombro, gire o peito para o lado oposto. \xd3timo para quem passa muito tempo no computador."]},{h:"2. Panturrilha",p:["M\xe3os na parede, uma perna estendida atr\xe1s com o calcanhar no ch\xe3o. Leve o quadril \xe0 frente."]},{h:"3. Lateral do tronco",p:["De lado para a parede, m\xe3o de dentro apoiada, bra\xe7o de fora sobre a cabe\xe7a, incline em dire\xe7\xe3o \xe0 parede."]},{h:"4. Pernas na parede",p:["Deitada com as pernas apoiadas na parede. Relaxa as pernas e \xe9 uma \xf3tima forma de terminar o dia."]},{h:"Lembrete",p:["Alongamento deve causar uma sensa\xe7\xe3o de estiramento confort\xe1vel. Se doer ou formigar, diminua a intensidade."]}]},{slug:"mobilidade",title:"Mobilidade para iniciantes",emoji:"\uD83D\uDD04",minutes:3,intro:"Flexibilidade \xe9 o quanto um m\xfasculo consegue alongar. Mobilidade \xe9 o quanto voc\xea consegue mover ativamente uma articula\xe7\xe3o, com controle. As duas se complementam.",sections:[{h:"Por que treinar mobilidade",p:["Articula\xe7\xf5es com boa mobilidade facilitam movimentos do dia a dia, como pegar algo em uma prateleira alta, agachar para amarrar o t\xeanis ou olhar para tr\xe1s ao dirigir."]},{h:"As regi\xf5es-chave",p:["Coluna tor\xe1cica (meio das costas), quadril e tornozelos costumam ficar r\xedgidos com o sedentarismo. Por isso aparecem tanto no desafio: rota\xe7\xe3o tor\xe1cica, c\xedrculos de quadril e mobilidade de tornozelo."]},{h:"Como praticar",p:["Movimentos lentos, sem balan\xe7o, dentro de uma amplitude confort\xe1vel. Repetir um pouco todos os dias funciona melhor do que muito de vez em quando."]}]},{slug:"constancia",title:"Como manter a const\xe2ncia",emoji:"\uD83D\uDCC6",minutes:4,intro:"Motiva\xe7\xe3o vai e vem. Const\xe2ncia \xe9 constru\xedda com estrat\xe9gia. Algumas ideias que funcionam para muita gente:",sections:[{h:"\xc2ncora o treino em um h\xe1bito",p:['"Depois de escovar os dentes de manh\xe3, eu fa\xe7o meu treino." Ligar o novo h\xe1bito a algo que voc\xea j\xe1 faz reduz o esfor\xe7o de lembrar.']},{h:"Regra dos 2 minutos",p:["Nos dias dif\xedceis, combine consigo mesma fazer s\xf3 o aquecimento. Muitas vezes voc\xea continua; e se n\xe3o continuar, ainda manteve o h\xe1bito vivo."]},{h:"Prepare o ambiente",p:["Deixe o tapete \xe0 vista, perto da parede. Quanto menos passos entre voc\xea e o treino, mais f\xe1cil come\xe7ar."]},{h:"Perder um dia n\xe3o \xe9 perder o desafio",p:['Se faltar um dia, retome no seguinte. No app, os dias perdidos ficam como "pendentes" e voc\xea pode recuper\xe1-los sem penalidade.']},{h:"Depois dos 21 dias",p:["Ao concluir, use a rotina de manuten\xe7\xe3o (A, B e C) 3 vezes por semana para manter o que conquistou."]}]},{slug:"cuidados",title:"Cuidados durante a pr\xe1tica",emoji:"\uD83E\uDE7A",minutes:3,intro:"O Pilates na Parede \xe9 de baixo impacto, mas todo exerc\xedcio f\xedsico pede aten\xe7\xe3o aos sinais do corpo.",sections:[{h:"Pare o exerc\xedcio se sentir",p:["Dor no peito, falta de ar desproporcional, tontura, vis\xe3o turva, dor aguda em articula\xe7\xf5es ou formigamento que n\xe3o passa. Se os sintomas persistirem, procure atendimento m\xe9dico."]},{h:"Converse com um profissional antes se",p:["Voc\xea est\xe1 gr\xe1vida ou teve parto recente, tem doen\xe7a card\xedaca, press\xe3o alta n\xe3o controlada, h\xe9rnia de disco, cirurgia recente, osteoporose ou qualquer condi\xe7\xe3o que exija acompanhamento."]},{h:"Ambiente seguro",p:["Use uma superf\xedcie que n\xe3o escorregue, afaste m\xf3veis com quinas e tenha \xe1gua por perto."]},{h:"Importante",p:["Este app oferece conte\xfado educativo e de bem-estar e n\xe3o substitui avalia\xe7\xe3o m\xe9dica, fisioterap\xeautica ou acompanhamento de um profissional de Educa\xe7\xe3o F\xedsica."]}]},{slug:"faq",title:"Perguntas frequentes",emoji:"\uD83D\uDCAC",minutes:4,intro:"As d\xfavidas mais comuns sobre o desafio.",sections:[{h:"Nunca fiz Pilates. Consigo acompanhar?",p:["Sim. A Fase 1 foi pensada para quem est\xe1 come\xe7ando, e todo exerc\xedcio tem uma vers\xe3o mais f\xe1cil."]},{h:"Quanto tempo leva cada treino?",p:["Depende do tempo que voc\xea escolheu no perfil: entre 10 e 30 minutos. O app ajusta as s\xe9ries para caber no seu dia."]},{h:"Preciso treinar todos os dias?",p:["O desafio libera um dia por vez. Se perder algum, ele fica pendente e voc\xea pode recuperar quando quiser, inclusive fazendo dois no mesmo dia, se se sentir bem."]},{h:"Vou emagrecer em 21 dias?",p:["Cada corpo responde de um jeito, e n\xe3o fazemos promessas de mudan\xe7a corporal espec\xedfica. O que o desafio busca \xe9 construir for\xe7a, mobilidade, postura e, principalmente, o h\xe1bito do movimento. Resultados de composi\xe7\xe3o corporal dependem tamb\xe9m de alimenta\xe7\xe3o, sono e continuidade."]},{h:"Meus dados ficam salvos onde?",p:["Somente neste aparelho e neste navegador. Se limpar os dados do navegador ou trocar de celular, o progresso n\xe3o \xe9 transferido. Em Perfil voc\xea pode exportar um backup."]},{h:"Os pontos servem para qu\xea?",p:["Os Pontos de Evolu\xe7\xe3o mostram o quanto voc\xea participou e fazem voc\xea subir de n\xedvel. Eles n\xe3o s\xe3o trocados por dinheiro ou produtos."]},{h:"Posso refazer um treino?",p:["Sim! Qualquer dia j\xe1 conclu\xeddo pode ser refeito a partir do calend\xe1rio. Os pontos do treino contam uma vez por dia do desafio."]}]}],r=e=>s.find(a=>a.slug===e)}}]);